        "speaker": null,
        "audio_url": null,
        "audio_url_vi": null,
        "raw_audio_en": "1P_15_i85_en.mp3",
        "raw_audio_vi": "1P_15_i85_vi.mp3",
        "raw_image": "1P_15_i85_im.png",
        "beat_prosody": "Let me ask you this, have you ever walked down the street and bought anything you see, right off the bat?",
        "part": "Part 6 - Dialogue",
        "source_sheet": "Topic 15",
